import openpyxl

wb = openpyxl.load_workbook('gdp.xlsx', data_only=True)
data_sheet = wb['Data']
task_sheet = wb['Task']

print('--- Data Sheet Row 3 (Header) ---')
# Iterate over cells in row 3
headers = {}
for cell in data_sheet[3]:
    if cell.value:
        headers[cell.column] = cell.value
        print(f'Col {cell.column} ({cell.column_letter}): {cell.value}')

print('\n--- Task Sheet Row 10 (Years) ---')
for cell in task_sheet[10]:
    if cell.value:
        print(f'Col {cell.column} ({cell.column_letter}): {cell.value}')

print('\n--- Task Sheet Column D (Series Codes) ---')
for row in range(12, 45):
    cell = task_sheet.cell(row=row, column=4)
    if cell.value:
        print(f'Row {row}: {cell.value}')

print('\n--- Task Sheet Labels (Stats) ---')
# Search for Min, Max, etc.
for row in task_sheet.iter_rows(min_row=35, max_row=60, min_col=1, max_col=15):
    for cell in row:
        if cell.value and isinstance(cell.value, str) and any(x in cell.value for x in ['Min', 'Max', 'Median', 'Mean', 'Percentile']):
            print(f'{cell.value} at {cell.coordinate}')
"
